-- ============================================================================
-- SEED — Fluxo de Processos DISTR (primeira versão publicada)
-- ============================================================================
-- Roda no SQL Editor do Supabase do report-DISTR (projeto report-distribuidora,
-- mesmo de esquema.sql). Insere a PRIMEIRA linha de dashboard_snapshots para
-- pagina='distr_fluxo' — sem essa linha a tela mostra "Nenhuma versão do fluxo
-- publicada ainda" (ver distr-fluxo.js, carregarDados()).
--
-- Não precisa de migração nenhuma: reaproveita a tabela dashboard_snapshots e
-- a RLS que já existem (leitura para todo autenticado, escrita só admin — ver
-- esquema.sql, seção 7). É exatamente o padrão que o próprio esquema já prevê
-- para páginas novas (seção 5, comentário "Hoje só existe a página 'estoque'").
--
-- Idempotente na medida certa: cada rodada cria uma NOVA versão (é assim que
-- o app versiona — nunca UPDATE), então só rode de novo se quiser mesmo
-- publicar outra vez o mesmo conteúdo.
-- ============================================================================

insert into dashboard_snapshots (pagina, payload)
values ('distr_fluxo', $seed_distr_fluxo${"versao_schema": 1, "titulo_pagina": "Fluxo de Processos — DISTR", "setores": ["Coleta", "Comercial", "Comprador", "Compras", "Devolução", "Embarque", "Estoque", "Fiscal", "Logística", "Personalização", "Planejamento", "Qualidade", "Recebimento", "Ressuprimento"], "lanes": [{"id": "principal", "titulo": "Fluxo principal — Recebimento → Armazenagem → Expedição", "sub": "Da chegada da carga agendada até o veículo liberado com o EDI enviado à transportadora. Cada fase recomeça sua própria numeração — é tratada como um processo à parte.", "fases": [{"id": "receb", "titulo": "Recebimento", "blocos": [["step", "1"], ["step", "2"], ["step", "3"], ["guard", "A quantidade bateu na conferência?", ["4.1", "4.2"], {"rejoin": true, "exc": "Não", "ok": "Sim"}], ["step", "4"], ["step", "5"], ["step", "6"], ["guard", "A reprova da carga está acima do % aceito?", ["6.1", "6.1.1", "6.1.2"], {"rejoin": false, "exc": "Sim", "ok": "Não"}], ["step", "7"], ["step", "8"], ["guard", "Foi identificada alguma ocorrência na conferência?", ["8.1", "8.2", "8.3", "8.4"], {"rejoin": true, "parallel": true, "exc": "Sim", "ok": "Não"}], ["step", "9"], ["step", "10"], ["step", "11"], ["guard", "Os endereços batem com o físico?", ["11.1"], {"rejoin": true, "exc": "Não", "ok": "Sim"}], ["step", "12"], ["step", "13"]]}, {"id": "armaz", "titulo": "Armazenagem e Ressuprimento", "blocos": [["step", "1"], ["step", "2"], ["step", "3"], ["step", "4"], ["step", "5"]]}, {"id": "exped", "titulo": "Expedição", "blocos": [["step", "1"], ["step", "2"], ["step", "3"], ["fork", "Qual a família do produto?", [["Vestuário", ["3A.1"]], ["Calçados, acessórios e meias", ["3B.1"]]]], ["guard", "O item foi 100% localizado no PICKING?", ["4.1", "4.2", "4.3", "4.4", "4.5", "4.6", "4.7"], {"rejoin": false, "exc": "Não", "ok": "Sim"}], ["step", "5"], ["fork", "Onde a conferência acontece?", [["COLMEIA — Vestuário", ["5A.1", "5A.2"]], ["ESTEIRA — Calçados", ["5B.1"]]]], ["step", "6"], ["step", "7"], ["gate", "8"], ["gate", "9"], ["step", "10"], ["step", "11"], ["step", "12"], ["step", "13"], ["step", "14"], ["step", "15"], ["guard", "A volumetria bateu na Ordem de Transporte?", ["15.1"], {"rejoin": true, "exc": "Não", "ok": "Sim"}], ["step", "16"]]}]}, {"id": "reversa", "titulo": "Fluxo de Reversa — Devolução", "sub": "Disparado pela chegada de um veículo com devolução, não pela sequência acima. Reinjeta material no ciclo de Ressuprimento (fase Armazenagem, etapa 1).", "fases": [{"id": "rever", "titulo": "Reversa e Devolução", "blocos": [["step", "1"], ["guard", "A caixa está violada ou com fita fora do padrão?", ["1.1", "1.2"], {"rejoin": true, "exc": "Sim", "ok": "Não"}], ["step", "2"], ["step", "3"], ["guard", "Faltou algum item na conferência?", ["3.1", "3.2"], {"rejoin": true, "parallel": true, "exc": "Sim", "ok": "Não"}], ["step", "4"], ["step", "5"], ["step", "6"]]}]}], "nos": {"receb:1": {"n": "1", "n_orig": "0", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Agendamento da carga", "nome_orig": "Agendamento da carga", "tipo": "principal", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "Fornecedor e comprador combinam por e-mail a janela — data e hora — para a entrega da carga.", "original": "Todo agendamento é realizado via e-mail e o fornecedor e comprador determiando janela aberta com data e hora para realizar agendamento da carga", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "cal"}, "receb:2": {"n": "2", "n_orig": "0.1", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Confirmação do agendamento", "nome_orig": "Confirmação do agendamento", "tipo": "seq", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "Chega o PDF da nota mais o romaneio ou a ordem de compra. O Ressuprimento então cria os parâmetros de endereçamento do produto no estoque.", "original": "Fornecedor( para eventos nacionais) Comprador (para eventos internacionais) enviam o pdf da nota mais o romaneio ou ordem de compra, após é enviado para o setor de ressuprimento criar parametros no estoque para endereçar o produto no armezen", "marco": "", "loop": "", "nota": "O responsável muda conforme a origem: fornecedor em eventos nacionais, comprador em eventos internacionais.", "terminal": false, "icone": "mail"}, "receb:3": {"n": "3", "n_orig": "1", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Descarregamento", "nome_orig": "Descarregamento", "tipo": "principal", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "Equipe terceirizada da transportadora descarrega separando por artigo, cor e tamanho, acompanhada por um colaborador Vulcabras que confere nota contra volumes recebidos.", "original": "Equipe tercerizada descarregada por conta da transportadora separando por artigo, cor e tamanhosendo acompanhado por um colaborador fazendo a contagem e conferência da nota vs volumes recebidos", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "truck"}, "receb:4": {"n": "4", "n_orig": "1.2", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Conferência de volumes no recebimento", "nome_orig": "Recebimento de material", "tipo": "principal", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "Confere a quantidade recebida. Batendo, o material segue para a Qualidade.", "original": "Conferência finalizada correta segue para a qualidade, ocorrendo erro na quantidade é realizado uma nova contagem, encontrando novamente falta é direcionado para o setor de logistica com comprovação e alegação no cte para futuros debitos", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "clip"}, "receb:4.1": {"n": "4.1", "n_orig": null, "novo": true, "extraido_de": "4", "fase": "receb", "nome": "Nova contagem por falta na quantidade", "nome_orig": "Nova contagem por falta na quantidade", "tipo": "desvio", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "A quantidade não bateu na conferência: é feita uma nova contagem antes de decidir o próximo passo.", "original": "Conferência finalizada correta segue para a qualidade, ocorrendo erro na quantidade é realizado uma nova contagem, encontrando novamente falta é direcionado para o setor de logistica com comprovação e alegação no cte para futuros debitos", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "refresh"}, "receb:4.2": {"n": "4.2", "n_orig": null, "novo": true, "extraido_de": "4", "fase": "receb", "nome": "Falta enviada à Logística — débito no CTE", "nome_orig": "Falta enviada à Logística — débito no CTE", "tipo": "desvio", "resp": "Recebimento / Logística", "orig": "—", "dest": "—", "resumo": "Persistindo a falta na recontagem, o caso vai para a Logística com comprovação e alegação no CTE, para débito futuro contra a transportadora.", "original": "Conferência finalizada correta segue para a qualidade, ocorrendo erro na quantidade é realizado uma nova contagem, encontrando novamente falta é direcionado para o setor de logistica com comprovação e alegação no cte para futuros debitos", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "report"}, "receb:5": {"n": "5", "n_orig": "2", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Lançamento da nota de entrada", "nome_orig": "Lançamento da nota de entrada", "tipo": "principal", "resp": "Fiscal", "orig": "—", "dest": "—", "resumo": "O Fiscal lança a nota e libera a NIV (Número Interno Vulcabras), que habilita a conferência.", "original": "Time fiscal faz o lançamento da nota e é liberado uma niv (numero interno vulcabras) para conferência", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "file"}, "receb:6": {"n": "6", "n_orig": "3", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Validação da Qualidade por amostragem", "nome_orig": "Validação da Qualidade", "tipo": "principal", "resp": "Qualidade", "orig": "—", "dest": "—", "resumo": "A Qualidade valida por amostragem o material descarregado.", "original": "Por amostragem, o time de qualidade valida o material descarregado", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "lupa"}, "receb:6.1": {"n": "6.1", "n_orig": "3.1", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Acionamento de Compras — reprova acima do limite", "nome_orig": "Acionamento de Compras", "tipo": "desvio", "resp": "Qualidade / Compras", "orig": "—", "dest": "ARMRP", "resumo": "Reprova acima do percentual aceito: Compras assume a negociação e a validação do caso direto com o fornecedor.", "original": "Em caso de reprova da carga acima da % aceita, a área de compras é acionada para negociação e validação do caso diretamente com o fornecedor", "marco": "", "loop": "", "nota": "O percentual aceito não está definido na planilha — precisa ser informado.", "terminal": false, "icone": "shake"}, "receb:6.1.1": {"n": "6.1.1", "n_orig": "3.1.1", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Inspeção de 100% do lote", "nome_orig": "Validação da Qualidade", "tipo": "desvio", "resp": "Qualidade", "orig": "—", "dest": "ARMRP", "resumo": "Após a negociação com o fornecedor, a Qualidade inspeciona todo o material descarregado — pode exigir mão de obra terceirizada.", "original": "Após a sinalização e negociação do Compras com o Fornecedor, o setor da qualidade deverá analisar todo o material descarregado (Talvez haja necessidade de mão de obra 3°)", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "lupaf"}, "receb:6.1.2": {"n": "6.1.2", "n_orig": "3.1.2", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Decisão da Diretoria sobre o lote", "nome_orig": "Análise da Diretoria", "tipo": "desvio", "resp": "Qualidade", "orig": "—", "dest": "ARMRP", "resumo": "O material avariado fica retido no ARMRP até a Diretoria decidir entre descarte ou incineração.", "original": "Após validação, o material avariado deve ficar no armazém de reprovados aguardando ação da diretoria para destinar os itens para descarte ou incineração", "marco": "", "loop": "", "nota": "", "terminal": true, "icone": "gavel"}, "receb:7": {"n": "7", "n_orig": "3.2", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Segregação no ARMRP — reprova abaixo do limite", "nome_orig": "Entrada do Material no Armazém Qualidade", "tipo": "principal", "resp": "Qualidade", "orig": "—", "dest": "ARMRP", "resumo": "Reprova abaixo do percentual aceito: só as peças reprovadas vão para o armazém de reprovados. O restante da carga segue o fluxo normal.", "original": "Em caso de reprova da carga abaixo da % aceita, somente o material reprovado é destinado ao armazém de reprova.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "boxx"}, "receb:8": {"n": "8", "n_orig": "3.3", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Conferência volume a volume", "nome_orig": "Conferência de material aprovado na qualidade", "tipo": "principal", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "Confere volume a volume contra o espelho da caixa e verifica se há ocorrência aberta que trave a nota.", "original": "É realizado a conferência volume a volume vs o espelho da caixa, finalizando é consultado a ocorrência para verificar se tem divergência de quantidade. Se localizado divergência é cancelado a contagem e faz uma nova recontagem, se novamente ocorrer divergencia vamos no fisico localizar essa divergencia e vamos informar o comprador, no momento que o material não é conferido o sistema lança falta no armft gerando uma ocorrência para o comprador resolver. Podemos ter outros tipos de ocorrencia sendo, quantidade, prazo de entrega ( nota fica parada e o comprador tem que fazer liberação), imposto (time fiscal precisa realizar a liberação).", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "boxes"}, "receb:8.1": {"n": "8.1", "n_orig": null, "novo": true, "extraido_de": "8", "fase": "receb", "nome": "Ocorrência de quantidade — recontagem", "nome_orig": "Ocorrência de quantidade — recontagem", "tipo": "desvio", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "Divergência de quantidade contra o espelho da caixa: cancela a contagem e reconta. Persistindo, valida no físico e informa o comprador.", "original": "É realizado a conferência volume a volume vs o espelho da caixa, finalizando é consultado a ocorrência para verificar se tem divergência de quantidade. Se localizado divergência é cancelado a contagem e faz uma nova recontagem, se novamente ocorrer divergencia vamos no fisico localizar essa divergencia e vamos informar o comprador, no momento que o material não é conferido o sistema lança falta no armft gerando uma ocorrência para o comprador resolver. Podemos ter outros tipos de ocorrencia sendo, quantidade, prazo de entrega ( nota fica parada e o comprador tem que fazer liberação), imposto (time fiscal precisa realizar a liberação).", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "refresh"}, "receb:8.2": {"n": "8.2", "n_orig": null, "novo": true, "extraido_de": "8", "fase": "receb", "nome": "Volume não conferido — falta no ARMFT", "nome_orig": "Volume não conferido — falta no ARMFT", "tipo": "desvio", "resp": "Recebimento", "orig": "—", "dest": "—", "resumo": "O volume não foi conferido: o sistema lança a falta no ARMFT e abre uma ocorrência para o comprador resolver.", "original": "É realizado a conferência volume a volume vs o espelho da caixa, finalizando é consultado a ocorrência para verificar se tem divergência de quantidade. Se localizado divergência é cancelado a contagem e faz uma nova recontagem, se novamente ocorrer divergencia vamos no fisico localizar essa divergencia e vamos informar o comprador, no momento que o material não é conferido o sistema lança falta no armft gerando uma ocorrência para o comprador resolver. Podemos ter outros tipos de ocorrencia sendo, quantidade, prazo de entrega ( nota fica parada e o comprador tem que fazer liberação), imposto (time fiscal precisa realizar a liberação).", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "alert"}, "receb:8.3": {"n": "8.3", "n_orig": null, "novo": true, "extraido_de": "8", "fase": "receb", "nome": "Ocorrência de prazo de entrega", "nome_orig": "Ocorrência de prazo de entrega", "tipo": "desvio", "resp": "Comprador", "orig": "—", "dest": "—", "resumo": "A nota fica parada até o comprador fazer a liberação do prazo de entrega.", "original": "É realizado a conferência volume a volume vs o espelho da caixa, finalizando é consultado a ocorrência para verificar se tem divergência de quantidade. Se localizado divergência é cancelado a contagem e faz uma nova recontagem, se novamente ocorrer divergencia vamos no fisico localizar essa divergencia e vamos informar o comprador, no momento que o material não é conferido o sistema lança falta no armft gerando uma ocorrência para o comprador resolver. Podemos ter outros tipos de ocorrencia sendo, quantidade, prazo de entrega ( nota fica parada e o comprador tem que fazer liberação), imposto (time fiscal precisa realizar a liberação).", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "clock"}, "receb:8.4": {"n": "8.4", "n_orig": null, "novo": true, "extraido_de": "8", "fase": "receb", "nome": "Ocorrência de imposto", "nome_orig": "Ocorrência de imposto", "tipo": "desvio", "resp": "Fiscal", "orig": "—", "dest": "—", "resumo": "Ocorrência de imposto identificada: o time Fiscal precisa fazer a liberação.", "original": "É realizado a conferência volume a volume vs o espelho da caixa, finalizando é consultado a ocorrência para verificar se tem divergência de quantidade. Se localizado divergência é cancelado a contagem e faz uma nova recontagem, se novamente ocorrer divergencia vamos no fisico localizar essa divergencia e vamos informar o comprador, no momento que o material não é conferido o sistema lança falta no armft gerando uma ocorrência para o comprador resolver. Podemos ter outros tipos de ocorrencia sendo, quantidade, prazo de entrega ( nota fica parada e o comprador tem que fazer liberação), imposto (time fiscal precisa realizar a liberação).", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "invoice"}, "receb:9": {"n": "9", "n_orig": "3.4", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Liberação de ocorrência", "nome_orig": "Liberação de ocorrência", "tipo": "principal", "resp": "Recebimento", "orig": "—", "dest": "AC190", "resumo": "Liberada a ocorrência, a nota é integrada automaticamente e a etiqueta de armazenagem é reimpressa. Sem nenhuma ocorrência, a impressão sai automática. A partir daqui o material fica disponível para venda e cativação no AC190.", "original": "Após a liberação da ocorrência a nota é integrada automaticamente e é realizado a reimpressão de etiqueta de armazenagem. Somente quando não tem ocorrência nenhuma o sistema impreme automaticamente. Após essa entrada o material fica disponível para venda e cativação no AC190", "marco": "Material passa a existir como vendável no AC190.", "loop": "", "nota": "", "terminal": false, "icone": "unlock"}, "receb:10": {"n": "10", "n_orig": "3.5", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Separação e colagem de etiquetas", "nome_orig": "Separação e colagem", "tipo": "principal", "resp": "Recebimento", "orig": "AC190", "dest": "AC190", "resumo": "As etiquetas são separadas por artigo, cor, tamanho e destino (PICKING ou PULMÃO). O colaborador cola cada etiqueta na caixa correspondente e aplica o strech no palete conforme a posição nas longarinas.", "original": "As etiquetas são separadas por artigos, cor, tamanho, picking e pulmão e direcionada para o colaborador colar e separar as caixar por picking e pulmão conforme direcionamento do sistema e colar a etiqueta na caixa correspondente é feito o strech no pallete conforme posição nas longarinas.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "tag"}, "receb:11": {"n": "11", "n_orig": "3.6", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Solicitação de posições de armazenagem", "nome_orig": "Solicitação de Posições para Armazenagem", "tipo": "principal", "resp": "Recebimento", "orig": "AC190", "dest": "AC190", "resumo": "O Recebimento pede ao time operacional posições segregadas por marca e segmento, imprime os endereços destino e bipa volume por volume contra o endereço, dando a entrada efetiva do material físico no estoque.", "original": "O time do recebimento solicita posições em estoque (Segregadas por Marca e Segmento) para o time operacional e imprime os endereços destino para realizar a bipagem volume por volume vs endereço e assim conseguir realizar a entrada efetiva do material físico no estoque", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "pin"}, "receb:11.1": {"n": "11.1", "n_orig": "3.6.1", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Nova listagem de endereços", "nome_orig": "Validação de novos endereços em caso de inconsistência", "tipo": "desvio", "resp": "Recebimento", "orig": "AC190", "dest": "AC190", "resumo": "Se a listagem de endereços não bate com as posições físicas encontradas durante a armazenagem, uma nova listagem é enviada ao Recebimento para fechar o processo e dar entrada no físico.", "original": "Caso a listagem de endereços não esteja em conformidade com as posições físicas identificadas durante a armazenagem, uma nova listagem deve ser encaminhada ao recebimento para finalização do processo e entrada do material no físico", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "refresh"}, "receb:12": {"n": "12", "n_orig": "4", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Liberação do material ao Ressuprimento", "nome_orig": "Recebimento libera o material", "tipo": "principal", "resp": "Recebimento / Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "Todos os itens do recebimento são destinados ao Ressuprimento para alocação no estoque físico.", "original": "Todos os itens do recebimento são destinados ao setor de ressuprimento para alocação do material no estoque físico", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "unlock"}, "receb:13": {"n": "13", "n_orig": "4.1", "novo": false, "extraido_de": null, "fase": "receb", "nome": "Movimentação dos paletes ao endereço", "nome_orig": "Operador de empilhadeira realiza a movimentação dos pallets do recebimento", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "A empilhadeira leva o material do recebimento até o porta-palete e os endereços sinalizados na etapa anterior.", "original": "O material é direcionado do setor de recebimento ao porta-palete/endereços sinalizados anteriormente", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "fork1"}, "armaz:1": {"n": "1", "n_orig": "5", "novo": false, "extraido_de": null, "fase": "armaz", "nome": "Ressuprimento preventivo", "nome_orig": "Ressuprimento Preventivo", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "O material com falta de estoque no PICKING é localizado manualmente e sinalizado ao Ressuprimento para abastecer as posições.", "original": "O material que é identificado com falta de estoque no PICKING é localizado manualmente e sinalizado ao time de ressuprimento para abastecer as posições de PICKING do estoque", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "shelf"}, "armaz:2": {"n": "2", "n_orig": "5.1", "novo": false, "extraido_de": null, "fase": "armaz", "nome": "Relatório de faltas ao operador", "nome_orig": "Direcionamento ao operador", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "Um relatório das faltas sinalizadas é extraído e direcionado aos operadores de empilhadeira, responsáveis por baixar o estoque do PULMÃO e entregar ao time de armazenagem.", "original": "Um relatório é extraído a partir das faltas sinalizadas na etapa anterior e direcionado aos operadores de empilhadeira responsáveis por baixar o estoque do PULMÃO e direcionar ao time de armazenagem", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "report"}, "armaz:3": {"n": "3", "n_orig": "5.2", "novo": false, "extraido_de": null, "fase": "armaz", "nome": "Abastecimento do PICKING", "nome_orig": "Direcionamento ao time de armazenagem", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "O time de armazenagem aloca o saldo — completo ou parcial — e abastece a necessidade do endereço de PICKING.", "original": "O time de armazenagem responsável por armazenar o saldo (COMPLETO ou PARCIAL) e abastecer a necessidade do endereço de PICKING, realiza a alocação do material", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "shelf"}, "armaz:4": {"n": "4", "n_orig": "5.3", "novo": false, "extraido_de": null, "fase": "armaz", "nome": "Paletização das sobras", "nome_orig": "Alocação das sobras de ressuprimento", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "Sobrando material baixado para o ressuprimento, os itens vão para um novo palete segregado por segmento e marca, aguardando retorno a um endereço de PULMÃO.", "original": "Em caso de sobra de material baixado para o ressuprimento, os itens são posicionados um novo pallet (Segregados por segmento e marca) e aguardam retorno a um novo endereço de pulmão", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "pallet"}, "armaz:5": {"n": "5", "n_orig": "5.4", "novo": false, "extraido_de": null, "fase": "armaz", "nome": "Retorno das sobras ao PULMÃO", "nome_orig": "Retorno do material baixado", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "O assistente da área indica ao Ressuprimento um endereço com capacidade suficiente para alocar os paletes que sobraram da etapa anterior.", "original": "O assistente da área direciona ao time de ressuprimento um novo endereço com capacidade suficiente para alocar os produtos paletizados que sobraram da etapa anterior", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "up"}, "exped:1": {"n": "1", "n_orig": "6", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Geração da PFA e cativação do material", "nome_orig": "PFA gerada e cativação de material", "tipo": "principal", "resp": "Comercial / Planejamento / Coleta", "orig": "AC190", "dest": "AC190", "resumo": "Criada e validada a PFA, a Logística agenda os clusters. Liberados os rótulos, o Planejamento imprime por marca e família.", "original": "Após a criação e validação da PFA  a logistica realiza o agendamento dos clusters, feito isso é disponibilizado para impressão dos rotulos, o planejamento realiza a impressão por marca e família", "marco": "A PFA é o documento que cativa o material e dispara toda a expedição.", "loop": "", "nota": "", "terminal": false, "icone": "stardoc"}, "exped:2": {"n": "2", "n_orig": "6.1", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Validação de prioridade", "nome_orig": "Validação de Prioridade", "tipo": "principal", "resp": "Planejamento", "orig": "AC190", "dest": "AC190", "resumo": "Após liberação do Comercial, o Planejamento avalia se a separação precisa de prioridade e, se precisar, alinha esse movimento com a operação.", "original": "Após liberação do comercial, o planejamento valida se há necessidade de prioridade na separação e realiza esse movimento com a operação", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "flag"}, "exped:3": {"n": "3", "n_orig": "7", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Início da separação", "nome_orig": "Time de coleta inicia a separação do material", "tipo": "principal", "resp": "Coleta", "orig": "AC190", "dest": "AC190", "resumo": "O time operacional inicia a coleta do material nos endereços de PICKING sinalizados pelo sistema.", "original": "Time operacional inicia a coleta do material nos endereços de picking sinalizados pelo sistema", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "hand"}, "exped:3A.1": {"n": "3A.1", "n_orig": "7.1.1", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Separação — Vestuário", "nome_orig": "Separação realizada pelo sistema", "tipo": "bifurcacao", "resp": "Coleta", "orig": "AC190", "dest": "AC190", "resumo": "Restrita à família Vestuário. Ao fim da coleta, o material vai para a COLMEIA para conferência e montagem de volumes.", "original": "Restrita somente aos materiais cuja a familia representa os produtos de \"Vestuário\" , no final da coleta o material é destinado à colmeia para conferência e montage de volumes", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "shirt"}, "exped:3B.1": {"n": "3B.1", "n_orig": "7.1.2", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Separação — Calçados, Acessórios e Meias", "nome_orig": "Separação realizada pela PFA", "tipo": "bifurcacao", "resp": "Coleta", "orig": "AC190", "dest": "AC190", "resumo": "Restrita a calçados, acessórios e meias. O destino final do material separado são as ESTEIRAS, para conferência e montagem de volumes.", "original": "Restrita aos itens de CALÇADOS, ACESSÓRIOS e MEIAS. Destino final do material separado é as esteiras para conferência e montagem de volumes", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "shoe"}, "exped:4.1": {"n": "4.1", "n_orig": "7.2.1", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Item não localizado no PICKING", "nome_orig": "Item não localizado em totalidade no endereço de picking", "tipo": "desvio", "resp": "Coleta / Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "Se a coleta não localiza 100% do item, o time aciona o assistente de ressuprimento para validação do material.", "original": "Caso o material não seja 100% localizado pela coleta, o time aciona o assistente de ressuprimento para validação do material", "marco": "Porta de entrada do maior bloco de B.O. do fluxo: 7.2.1 a 7.2.8.", "loop": "", "nota": "", "terminal": false, "icone": "alert"}, "exped:4.2": {"n": "4.2", "n_orig": "7.2.2", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Relatório de baixa do PULMÃO", "nome_orig": "Time de ressuprimento acionado pela separação", "tipo": "desvio", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "O assistente da área gera um relatório indicando ao operador de empilhadeira os endereços de PULMÃO e os volumes que precisam ser baixados para a coleta.", "original": "Um relatório é gerado pelo assistente da área onde é sinalizado ao operador de empilhadeira os endereços de PULMÃO e os volumes que necessitam ser baixados para a coleta", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "report"}, "exped:4.3": {"n": "4.3", "n_orig": "7.2.3", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Remanejo para endereço provisório", "nome_orig": "Saldo do PULMÂO é remanejado para o endereço provisório", "tipo": "desvio", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "O saldo a ser ressuprido vai para o endereço 500.03.001 e os itens pendentes são entregues à coleta. Usado o material, o saldo segue para o 600.03.001, onde aguarda subida e alocação em nova posição de PULMÃO.", "original": "O saldo que deve ser ressuprido é encaminhado ao endereço 500.03.001 e os itens pendentes entregues à coleta. Após utilização do material o saldo é enviado ao endereço 600.03.001 e é onde fica aguardando subida e alocação em uma nova posição de PULMÃO", "marco": "", "loop": "", "nota": "Responsável definido nesta revisão: Ressuprimento. Os endereços 500.03.001 e 600.03.001 são de PULMÃO dentro do AC190 (não são PICKING) — usados só para movimentação provisória. Item parado ali não fica cativado por PFA importada.", "terminal": false, "icone": "pin"}, "exped:4.4": {"n": "4.4", "n_orig": "7.2.5", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Furo de estoque no PULMÃO", "nome_orig": "Material no PULMÃO não é localizado por furo de estoque", "tipo": "desvio", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "A divergência é sinalizada ao assistente da área. Confirmado que o material não está no endereço indicado, outra localização é entregue ao operador para baixar um novo palete.", "original": "A divergência é sinalizada ao assistente da área e caso o material realmente não esteja no endereço indicado, outra localizaçã é entregue ao operador para baixar um novo pallet com o material necessário", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "alert"}, "exped:4.5": {"n": "4.5", "n_orig": "7.2.6", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Varredura física e rastreio de movimentação", "nome_orig": "Time realiza uma validação mais detalhada físicamente como uma última tentativa de localizar o material", "tipo": "desvio", "resp": "Estoque", "orig": "AC190", "dest": "AC190", "resumo": "Última tentativa de achar o material: varre o quadrante em volta — principalmente endereços marcados como VAZIOS, caso clássico de inversão na armazenagem — e depois rastreia o histórico de movimentação dos volumes conjugados. Para não travar a separação, o saldo vai ao endereço 027.03.001.", "original": "A validação é realizada no quadrante em volta (Principalmente nos endereços sinalizados como VAZIOS no sistema, em caso de inversão na hora de armazenar o pallet). Em sequência é feita uma validação pelo histórico de movimentação dos volumes conjugados àqueles que foram sinalizados com divergência (A fim de rastrear a movimentação total dos volumes e pallets). Para realizar a análise e o material não ficar pendente de separação, o saldo é destinado ao endereço 027.03.001.", "marco": "", "loop": "", "nota": "O endereço 027.03.001 é de PULMÃO dentro do AC190 (não é PICKING) — usado só para movimentação provisória. Item parado ali não fica cativado por PFA importada.", "terminal": false, "icone": "lupaf"}, "exped:4.6": {"n": "4.6", "n_orig": "7.2.7", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Descativação e envio ao ARAMO", "nome_orig": "Material enviado ao ARAMO", "tipo": "desvio", "resp": "Estoque", "orig": "AC190", "dest": "ARAMO", "resumo": "Em último caso, não localizados os itens pendentes, descativa a reserva no PICKING e envia o saldo ao armazém ARAMO.", "original": "Em último caso, se não localizarmos os itens pendentes, se vê necessário realizar a descativação dos itens reservados no PICKING e após isso envio de saldo ao armazém ARAMO", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "boxx"}, "exped:4.7": {"n": "4.7", "n_orig": "7.2.8", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Reajuste da PFA", "nome_orig": "Se o material não for localizado é necessário realizar o reajuste da PFA", "tipo": "desvio", "resp": "Coleta / Planejamento / Comercial", "orig": "AC190", "dest": "AC190", "resumo": "Divergência não solucionada: assim que os demais itens passam pela conferência, o Planejamento ajusta a PFA junto ao Comercial, sempre com base no relatório final da conferência.", "original": "No caso de divergência de material não solucionada, assim que todos os demais itens passam pela conferência, o material é sinalizado ao time de planejamento que ajusta a PFA com o Comercial, sempre baseado no relatório final da conferência", "marco": "", "loop": "", "nota": "", "terminal": true, "icone": "stardoc"}, "exped:5": {"n": "5", "n_orig": "7.3", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Entrega ao ponto de conferência", "nome_orig": "Após finalização da coleta o material é entregue ao caixa de conferência", "tipo": "principal", "resp": "Coleta", "orig": "AC190", "dest": "AC190", "resumo": "Concluída a separação, o material vai para o seu ponto de conferência — COLMEIA ou ESTEIRA. Alocado 100% no buffer, o time de conferência é acionado para a contagem do pedido.", "original": "Após finalização da separação, o material é direcionado ao seu respectivo ponto de conferência (COLMEIA ou ESTEIRA) onde após ser 100% alocado no buffer, o time de conferência é acionado para contagem do pedido", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "clip"}, "exped:5A.1": {"n": "5A.1", "n_orig": "7.4.1", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Alocação na COLMEIA", "nome_orig": "Alocação de itens na COLMEIA", "tipo": "bifurcacao", "resp": "Coleta", "orig": "AC190", "dest": "AC190", "resumo": "O coletor indica ao colaborador que inicie a conferência. Ao bipar os produtos, o sistema acende uma luz no escaninho de destino. Escaninhos completos ficam verdes. Concluído 100%, a coleta é remanejada para outra atividade e a conferência é acionada.", "original": "Após a finalização da separação o coletor indica ao colaborador para iniciar a conferência. Ao começar a bipagem dos produtos o escaninho de destino é sinalizado pelo sistema com uma luz indicando o local de armazenagem. Conforme a armazenagem vai sendo finalizada, os escaninhos completos são marcados com uma luz verde pelo sistema na parte interna da estrutura. Assim que for 100% concluída o time da coleta é direcionado para outra atividade e o time de conferência é acionado", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "grid"}, "exped:5A.2": {"n": "5A.2", "n_orig": "7.4.2", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Conferência e encaixotamento", "nome_orig": "Conferência realizada na COLMEIA", "tipo": "bifurcacao", "resp": "Coleta", "orig": "AC190", "dest": "—", "resumo": "Os escaninhos verdes têm o QR Code bipado e os itens conferidos em seguida. O material é encaixotado contando o pedido por transportadora e volumetria da PFA, depois paletizado, lacrado com fita e direcionado ao embarque.", "original": "Após armazenagem, os escaninho sinalizados em verde tem seu Qrcode bipado e seus itens conferidos logo em sequência. O material é encaixotado fazendo a contagem do pedido POR TRANSPORTADORA E VOLUMETRIA DA PFA e logo em seguida paletizados, lacrados com fita e direcionados ao setor de embarque.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "grid"}, "exped:5B.1": {"n": "5B.1", "n_orig": "7.5", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Conferência na ESTEIRA", "nome_orig": "Conferência realizada na ESTEIRA", "tipo": "bifurcacao", "resp": "Coleta", "orig": "AC190", "dest": "—", "resumo": "Pedidos 100% separados vão ao time de conferência da esteira: leitura do rótulo, contagem dos itens, encaixotamento, lacre e posicionamento nos paletes — também ajustados por volumetria e transportadora.", "original": "Os pedidos 100% separados são encaminhados ao time de conferência da esteira, eles realizam a leitura do rótulo e contagem dos itens. Os produtos são encaixotados e levados pela esteira até serem lacrados e ter seu posicionamento ajustado nos pallets (Também ajustados por VOLUMETRIA e TRANSPORTADORA).", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "belt"}, "exped:6": {"n": "6", "n_orig": "7.6", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Personalização do material", "nome_orig": "Personalização de material (SOMENTE CASO O MATERIAL FOR PERSONALIZADO, SE NÃO ELE PULA ESSA PARTE)", "tipo": "principal", "resp": "Coleta / Personalização", "orig": "—", "dest": "—", "resumo": "Só acontece se o pedido for personalizado — caso contrário a etapa é pulada. A origem pode ser tanto a ESTEIRA quanto a COLMEIA. Os itens e detalhes vêm vinculados à PFA e a personalização segue as especificações do cliente e do segmento.", "original": "O material a ser personalizado pode ter sua origem tanto da ESTEIRA quanto da COLMEIA . Os itens e detalhes da personalização são vinculados diretamente à PFA, o material é direcionado ao setor da personalização e são personalizados de acordo com as especificações do cliente e segmentos.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "brush"}, "exped:7": {"n": "7", "n_orig": "8", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Faturamento e emissão da Nota Fiscal", "nome_orig": "Pedido direcionado ao Fiscal para faturamento e emissão de Nota Fiscal", "tipo": "principal", "resp": "Fiscal", "orig": "—", "dest": "—", "resumo": "O Fiscal gera a NF e a disponibiliza para impressão no setor de embarque.", "original": "Fiscal gera NF e disponibiliza ela para impressão ao setor de embarque", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "invoice"}, "exped:8": {"n": "8", "n_orig": "8.1", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Bloqueio de quarentena", "nome_orig": "Bloqueio de quarentena", "tipo": "gate", "resp": "Sistema (bloqueio automático)", "orig": "—", "dest": "—", "resumo": "Todo pedido nasce bloqueado. Após a primeira leitura, o bloqueio cai sozinho em 5 minutos — desde que o cluster esteja agendado para a demanda do dia. Se não estiver, o agendamento é feito manualmente.", "original": "Todo pedido inicialmente tem um bloqueio que após liberada a primeira leitura, é necessário um tempo de 5 minutos para que esse bloqueio seja retirado automaticamente (Se o cluster tiver agendado para a demanda do dia, caso não, o agendamento é realizado manualmente)", "marco": "", "loop": "", "nota": "Não tem dono humano — é uma regra automática do sistema, não uma etapa executada por uma área. Ela mesma se retira sozinha 5 minutos após a primeira leitura, desde que o cluster esteja agendado para a demanda do dia; se não estiver, o agendamento é feito manualmente.", "terminal": false, "icone": "clock"}, "exped:9": {"n": "9", "n_orig": "8.1.1", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Bloqueio de entrega programada", "nome_orig": "Bloqueio de entrega programada", "tipo": "gate", "resp": "Comercial", "orig": "—", "dest": "—", "resumo": "O Comercial cria uma data de liberação de faturamento para a PFA. Só o Comercial pode remover esse bloqueio para antecipar faturamento e embarque.", "original": "O setor Comercial cria uma data de liberação de faturamento para a PFA, somente a área comercial pode retirar esse bloqueio para antecipar a data de faturamento e embarque", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "callock"}, "exped:10": {"n": "10", "n_orig": "9", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Liberação e separação das NFs", "nome_orig": "Liberação de NF para o embarque", "tipo": "principal", "resp": "Fiscal / Embarque", "orig": "—", "dest": "—", "resumo": "Disponibilizada a nota, o embarque grampeia e separa as NFs, segregando por transportadora, volume e PFA, em ordem.", "original": "Após disponibilizar a nota para o embarque, o setor responsável grampeia e faz a separação das NFs, segregando respectivamente por transportadora, volume e PFA (Em ordem).", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "invoice"}, "exped:11": {"n": "11", "n_orig": "9.1", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Vínculo da NF ao pedido", "nome_orig": "NF vinculada ao pedido", "tipo": "principal", "resp": "Embarque", "orig": "—", "dest": "—", "resumo": "A nota é encaixada no respectivo pedido, que já deve estar completo no box do embarque.", "original": "A nota é encaixada no respectivo pedido que deverá estar completo já no box do embarque", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "file"}, "exped:12": {"n": "12", "n_orig": "9.2", "novo": false, "extraido_de": null, "fase": "exped", "nome": "2ª leitura e conferência dos volumes", "nome_orig": "2° Leitura/Conferência  dos volumes", "tipo": "principal", "resp": "Embarque", "orig": "—", "dest": "—", "resumo": "O código de barras da nota é lido com o coletor e bipado em todos os volumes do pedido, independentemente da volumetria.", "original": "O código de barras da nota é lido com o coletor e bipado em todos os volumes do pedido, independente da volumetria", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "barcode"}, "exped:13": {"n": "13", "n_orig": "9.3", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Etiqueta de roteirização e embarque", "nome_orig": "Colagem de etiqueta de roteirização e embarque", "tipo": "principal", "resp": "Embarque", "orig": "—", "dest": "—", "resumo": "Só depois de lidos todos os volumes da NF a etiqueta de roteirização é gerada e colada nos respectivos volumes. O material então vai para a transportadora conferir NOTA × VOLUME e iniciar o carregamento.", "original": "Somente após a leitura de todos os volumes da NF, a etiqueta de roteirização é gerada e colada em seus respectivos volumes. Após isso o material é destinado à transportadora realizar aconferência da NOTAxVOLUME para dar inicio ao carregamento", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "route"}, "exped:14": {"n": "14", "n_orig": "9.4", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Confirmação de volumetria pela transportadora", "nome_orig": "Confirmação de volumetria pela transportadora", "tipo": "principal", "resp": "Embarque", "orig": "—", "dest": "—", "resumo": "Depois do carregamento, o conferente da transportadora informa a volumetria carregada e envia as notas ao embarque para liberação do veículo.", "original": "Após o carregamento o conferente da transportadora informa a volumetria carregada e envia as notas para o setor de embarque fazer a liberação do veículo", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "truck"}, "exped:15": {"n": "15", "n_orig": "9.5", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Validação final de volumetria na OT", "nome_orig": "Validação final de volumatria na OT", "tipo": "principal", "resp": "Embarque", "orig": "—", "dest": "—", "resumo": "Todas as notas entram numa Ordem de Transporte e são confrontadas com a quantidade de volumes informada pelo conferente. Correto, o processo é finalizado.", "original": "Todas as notas são incluídas em uma Ordem de Transporte e confrontadas com a quantidade de volumes informada pelo conferente, se correta, finaliza o processo. Se não, o conferente descarrega o veículo para iniciar a recontagem do material.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "listc"}, "exped:15.1": {"n": "15.1", "n_orig": null, "novo": true, "extraido_de": "15", "fase": "exped", "nome": "Volumetria divergente — descarrega e reconta", "nome_orig": "Volumetria divergente — descarrega e reconta", "tipo": "desvio", "resp": "Embarque", "orig": "—", "dest": "—", "resumo": "A volumetria não bateu na Ordem de Transporte: o conferente descarrega o veículo e inicia a recontagem do material.", "original": "Todas as notas são incluídas em uma Ordem de Transporte e confrontadas com a quantidade de volumes informada pelo conferente, se correta, finaliza o processo. Se não, o conferente descarrega o veículo para iniciar a recontagem do material.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "refresh"}, "exped:16": {"n": "16", "n_orig": "9.6", "novo": false, "extraido_de": null, "fase": "exped", "nome": "Liberação do veículo e envio do EDI", "nome_orig": "Etapa final de embarque", "tipo": "principal", "resp": "Embarque", "orig": "—", "dest": "—", "resumo": "O conferente da transportadora envia todas as notas, o veículo é liberado e é gerada a OT que compõe todas as NFs carregadas no baú. Estando correto, gera o EDI e envia por e-mail à transportadora.", "original": "O conferente da transportadora envia todas as notas para o fluxo ser finalizado com a liberação do veículo. É gerado uma OT que compõe todas as NFs carregadas no baú, se correto, gera um EDI e envia para a transportadora por email.", "marco": "Fim do fluxo de saída.", "loop": "", "nota": "", "terminal": true, "icone": "truck"}, "rever:1": {"n": "1", "n_orig": "10", "novo": false, "extraido_de": null, "fase": "rever", "nome": "Devolução agendada", "nome_orig": "Devolução agendada", "tipo": "principal", "resp": "Devolução", "orig": "—", "dest": "—", "resumo": "A devolução é agendada por e-mail informando todas as NFs que darão entrada no CD. No dia, o motorista se apresenta na portaria e entrega as NFs acompanhadas da AD (Autorização de Devolução). O veículo é descarregado e o material conferido VOLUME × NOTA. Correto, o conhecimento é assinado e o motorista liberado.", "original": "A devolução é agendada por email, informando todas as NFs que darão entrada por devolução no CD. No dia da agenda o motorista se apresenta na portaria, e entrega todas as NFs onde as mesmas deverão acompanhando a AD (Autorização de Devolução), veículo é descarregado e o material é conferido da forma VOLUME x NOTA. Se correto o CONHECIMENTO é assinado e o motorista liberado. Se alguma caixa apresentar alguma violação ou fita transparente sem o rótulo padronizado na política de transporte, a mesma é aberta e conferida ITEM a ITEM. Se OK o motorista é liberado, se caso haja alguma divergência é relatado no CTE (conhecimento de frete) os volumes são fotografados mostrando a violação isso é enviado por email para a logística de PAROBÉ as fotos e o CTE com a alegação no verso para a geração do LOG (Débito) contra a transportadora.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "ret"}, "rever:1.1": {"n": "1.1", "n_orig": null, "novo": true, "extraido_de": "1", "fase": "rever", "nome": "Caixa violada — conferência item a item", "nome_orig": "Caixa violada — conferência item a item", "tipo": "desvio", "resp": "Devolução", "orig": "—", "dest": "—", "resumo": "Caixa com violação ou fita transparente sem o rótulo padronizado da política de transporte: é aberta e conferida item a item. Estando OK, o motorista é liberado.", "original": "A devolução é agendada por email, informando todas as NFs que darão entrada por devolução no CD. No dia da agenda o motorista se apresenta na portaria, e entrega todas as NFs onde as mesmas deverão acompanhando a AD (Autorização de Devolução), veículo é descarregado e o material é conferido da forma VOLUME x NOTA. Se correto o CONHECIMENTO é assinado e o motorista liberado. Se alguma caixa apresentar alguma violação ou fita transparente sem o rótulo padronizado na política de transporte, a mesma é aberta e conferida ITEM a ITEM. Se OK o motorista é liberado, se caso haja alguma divergência é relatado no CTE (conhecimento de frete) os volumes são fotografados mostrando a violação isso é enviado por email para a logística de PAROBÉ as fotos e o CTE com a alegação no verso para a geração do LOG (Débito) contra a transportadora.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "alert"}, "rever:1.2": {"n": "1.2", "n_orig": null, "novo": true, "extraido_de": "1", "fase": "rever", "nome": "Divergência — CTE e LOG à transportadora", "nome_orig": "Divergência — CTE e LOG à transportadora", "tipo": "desvio", "resp": "Devolução", "orig": "—", "dest": "—", "resumo": "Havendo divergência na conferência item a item: relata no CTE, fotografa os volumes mostrando a violação e envia à logística de Parobé para gerar o LOG (débito) contra a transportadora.", "original": "A devolução é agendada por email, informando todas as NFs que darão entrada por devolução no CD. No dia da agenda o motorista se apresenta na portaria, e entrega todas as NFs onde as mesmas deverão acompanhando a AD (Autorização de Devolução), veículo é descarregado e o material é conferido da forma VOLUME x NOTA. Se correto o CONHECIMENTO é assinado e o motorista liberado. Se alguma caixa apresentar alguma violação ou fita transparente sem o rótulo padronizado na política de transporte, a mesma é aberta e conferida ITEM a ITEM. Se OK o motorista é liberado, se caso haja alguma divergência é relatado no CTE (conhecimento de frete) os volumes são fotografados mostrando a violação isso é enviado por email para a logística de PAROBÉ as fotos e o CTE com a alegação no verso para a geração do LOG (Débito) contra a transportadora.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "report"}, "rever:2": {"n": "2", "n_orig": "10.1", "novo": false, "extraido_de": null, "fase": "rever", "nome": "Geração da NIV e da minuta cega", "nome_orig": "Geração de NIV", "tipo": "principal", "resp": "Devolução / Fiscal", "orig": "—", "dest": "—", "resumo": "As NFs vão ao Fiscal para gerar a NIV e imprimir a minuta cega usada na conferência.", "original": "NFs são enviadas para o Fiscal realizar a geração do NIV e impressão da minuta cega para a conferência", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "file"}, "rever:3": {"n": "3", "n_orig": "10.2", "novo": false, "extraido_de": null, "fase": "rever", "nome": "Conferência item a item", "nome_orig": "Conferência do material", "tipo": "principal", "resp": "Devolução", "orig": "—", "dest": "DEVFT / ARAMO", "resumo": "A conferência é feita item a item contra a minuta cega.", "original": "A conferência é realizada item a item e o item que não constar no volume físico é lançado no DEVFT para a geração de débito contra a transportadora se o volume estiver com a fita lacre intacta e ocorrer a falta interna, a responsabilidade fica para o CD assumir e a falta é lançada no ARAMO para futuro ajuste.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "listc"}, "rever:3.1": {"n": "3.1", "n_orig": null, "novo": true, "extraido_de": "3", "fase": "rever", "nome": "Item ausente com lacre violado — DEVFT", "nome_orig": "Item ausente com lacre violado — DEVFT", "tipo": "desvio", "resp": "Devolução", "orig": "—", "dest": "—", "resumo": "O item não consta no volume físico e o lacre está violado: lança no DEVFT e gera débito contra a transportadora.", "original": "A conferência é realizada item a item e o item que não constar no volume físico é lançado no DEVFT para a geração de débito contra a transportadora se o volume estiver com a fita lacre intacta e ocorrer a falta interna, a responsabilidade fica para o CD assumir e a falta é lançada no ARAMO para futuro ajuste.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "boxx"}, "rever:3.2": {"n": "3.2", "n_orig": null, "novo": true, "extraido_de": "3", "fase": "rever", "nome": "Item ausente com lacre intacto — ARAMO", "nome_orig": "Item ausente com lacre intacto — ARAMO", "tipo": "desvio", "resp": "Devolução", "orig": "—", "dest": "—", "resumo": "O item não consta no volume físico mas o lacre está intacto (falta interna): a responsabilidade é do CD e a falta é lançada no ARAMO para ajuste futuro.", "original": "A conferência é realizada item a item e o item que não constar no volume físico é lançado no DEVFT para a geração de débito contra a transportadora se o volume estiver com a fita lacre intacta e ocorrer a falta interna, a responsabilidade fica para o CD assumir e a falta é lançada no ARAMO para futuro ajuste.", "marco": "", "loop": "", "nota": "", "terminal": false, "icone": "boxin"}, "rever:4": {"n": "4", "n_orig": "11", "novo": false, "extraido_de": null, "fase": "rever", "nome": "Integração da NIV", "nome_orig": "Finalização de conferência e integração de NIV", "tipo": "principal", "resp": "Devolução / Ressuprimento", "orig": "—", "dest": "AC190", "resumo": "Concluída a conferência, a NIV é integrada e o volume é gerado. O material segue ao Ressuprimento para armazenagem.", "original": "Concluindo a conferência, a NIV é integrada e gerado o volume para a conferência. O material então é direcionado para o setor de ressuprimento realizar a armazenagem", "marco": "Ponto onde a Reversa reinjeta material no estoque vendável (AC190).", "loop": "", "nota": "", "terminal": false, "icone": "boxin"}, "rever:5": {"n": "5", "n_orig": "11.1", "novo": false, "extraido_de": null, "fase": "rever", "nome": "Armazenagem no PICKING via 098.03.001", "nome_orig": "Time de ressuprimento tenta armazenar o material no PICKING do endereço 098.03.001", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "Na devolução, as etiquetas que viriam do recebimento para alocação no PULMÃO são imputadas direto no sistema. Como o saldo devolvido é pequeno — são devoluções parciais — o material vai do 098.03.001 direto para o PICKING.", "original": "Quando o matrial da entrada por devolução as etiquetas que deveriam vir do recebimento para alocação no PULMÃO são imputadas diretamente no sistema, como o saldo devolvido não é um grande volume (Pois são devoluções parciais) de inicio o material é transferido do 098 para o PICKING", "marco": "", "loop": "Daqui o material volta a circular pelo ciclo de Ressuprimento (etapa 5) e fica disponível para nova separação (etapa 7).", "nota": "O endereço 098.03.001 é de PULMÃO dentro do AC190 (não é PICKING) — usado só para movimentação provisória. Item parado ali não fica cativado por PFA importada.", "terminal": false, "icone": "shelf"}, "rever:6": {"n": "6", "n_orig": "11.2", "novo": false, "extraido_de": null, "fase": "rever", "nome": "Sobras etiquetadas ao PULMÃO", "nome_orig": "Em caso de sobras de itens, o material é etiquetado e levado ao PULMÃO", "tipo": "principal", "resp": "Ressuprimento", "orig": "AC190", "dest": "AC190", "resumo": "Havendo sobra por conta da volumetria devolvida, o sistema imprime as etiquetas, elas são vinculadas aos respectivos volumes e o operador de empilhadeira aloca os produtos no PULMÃO.", "original": "Caso haja sobra de material por conta da volumetria devolvida, os itens tem sua etiqueta impressa direto do sistema e elas são vinculadas aos seus respectivos volumes, e o material é direcionado ao operador de empilhadeira que irá realizar a alocação dos produtos devolvidos no PULMÃO. Caso o material fique muito tempo sem subir para seu endereço de PULMÃO, fica sujeito a cativação pela criação de alguma PFA (Caso a PFA cative um material no PICKING ele fica impossibilitado de sofrer ajustes ou movimentações para correção)", "marco": "", "loop": "", "nota": "Se o material demorar a subir para o PULMÃO, fica sujeito a cativação por uma PFA — e material cativado no PICKING não aceita ajuste nem movimentação de correção. Mantido como observação de risco nesta etapa; não virou nó próprio por não descrever uma ação de resposta, só um alerta.", "terminal": false, "icone": "up"}}, "armazens": [{"cod": "AC190", "uso": "Vendável — armazém de material físico (PULMÃO e PICKING)", "resp": "Estoque", "dono": "Claudeir e Fernando", "tt": false, "acao": "", "status": "ativo"}, {"cod": "ARAMO", "uso": "Material em análise (sobras)", "resp": "Estoque", "dono": "Claudeir e Fernando", "tt": true, "acao": "Falhas operacionais e ajustes de faltas de outras unidades", "status": "ativo"}, {"cod": "ARMC1", "uso": "Material de insumo", "resp": "Almoxarifado", "dono": "Claudeir e Fernando", "tt": false, "acao": "", "status": "ativo"}, {"cod": "ARMFT", "uso": "Faltas de recebimento", "resp": "Compras", "dono": "Angelo", "tt": false, "acao": "Faltas no recebimento — Angelo trata com o fornecedor", "status": "ativo"}, {"cod": "DEVFT", "uso": "Faltas de devolução", "resp": "Transporte", "dono": "Zuch", "tt": true, "acao": "Atuar com as transportadoras", "status": "ativo"}, {"cod": "ARMRP", "uso": "Material reprovado na qualidade", "resp": "Qualidade", "dono": "Matheus", "tt": false, "acao": "Peças fora do padrão da marca", "status": "ativo"}, {"cod": "DEVRP", "uso": "Material de devolução reprovado na qualidade", "resp": "Qualidade", "dono": "Matheus", "tt": false, "acao": "Peças fora do padrão da marca devolvidas pelo cliente", "status": "ativar"}, {"cod": "XXXX", "uso": "Armazém do Recebimento — ainda não criado", "resp": "Recebimento", "dono": "Gilma", "tt": true, "acao": "Criar armazém para o recebimento com T+ / T−", "status": "criar"}], "pendencias": [{"id": 1, "cat": "Numeração", "status": "resolvido", "txt": "Numeração inteira/decimal/letra redesenhada por completo nesta revisão — sem lacunas, com regra explicada no topo da página.", "ref": "geral"}, {"id": 2, "cat": "Conteúdo", "status": "resolvido", "txt": "<b>7.2.4</b> (duplicata de 7.3) foi removida. Manteve-se apenas 7.3, agora renumerada.", "ref": "exped 5"}, {"id": 3, "cat": "Responsável", "status": "resolvido", "txt": "Responsável de 7.2.3/7.2.4 definido como <b>Ressuprimento</b>.", "ref": "exped 4.3"}, {"id": 4, "cat": "Responsável", "status": "resolvido", "txt": "8.1 (bloqueio de quarentena) passou a ter responsável explícito: <b>Sistema (bloqueio automático)</b> — não é uma área, é uma regra do sistema.", "ref": "exped 8"}, {"id": 5, "cat": "Conteúdo", "status": "resolvido", "txt": "Os 6 blocos com B.O. escondido no texto corrido (antigas 1.2, 3.3, 9.5, 10, 10.2) viraram 11 etapas numeradas próprias, cada uma com sua linha e espaçamento visível.", "ref": "geral"}, {"id": 6, "cat": "Conteúdo", "status": "resolvido", "txt": "Nomes padronizados para o mesmo registro (substantivo curto) em todas as etapas.", "ref": "geral"}, {"id": 7, "cat": "Responsável", "status": "resolvido", "txt": "Responsáveis compostos com barra (“Comercial/Planejamento/Coleta” etc.) representam um <b>handoff em sequência</b>, não co-responsabilidade simultânea — ex.: o Comercial gera a PFA, o Planejamento delega à Coleta, a Coleta inicia a separação. No detalhe de cada etapa isso agora aparece como cadeia (A → B → C).", "ref": "vários"}, {"id": 8, "cat": "Armazém", "status": "resolvido", "txt": "“x”/“X” em origem e destino confirmado: significa que a etapa <b>não movimenta estoque</b>. Quando origem é “x” e o destino é um armazém real, é o ponto onde o material <b>passa a existir</b> naquele armazém — não é uma transferência de outro lugar. Essa leitura agora aparece no detalhe de cada etapa.", "ref": "vários"}, {"id": 9, "cat": "Armazém", "status": "resolvido", "txt": "Os endereços 500.03.001, 600.03.001, 027.03.001 e 098.03.001 são todos de <b>PULMÃO dentro do AC190</b> (nenhum é PICKING) — usados para movimentação provisória. Item parado neles <b>não fica cativado</b> por PFA importada. Nota adicionada nas etapas que os citam.", "ref": "exped 4.3, 4.5 · rever 5"}, {"id": 10, "cat": "Armazém", "status": "resolvido", "txt": "Confirmado: <b>XXXX</b> (armazém do Recebimento) ainda não foi definido, mas será criado. <b>DEVRP</b> já existe fisicamente, só falta ser parametrizado no sistema.", "ref": "Div_ARM"}]}$seed_distr_fluxo$::jsonb);
